export const portraitExample={...defaults,focal:85,aperture:1.4,mode:'A',subject:4,focus:4,foreground:2.4,background:18,sculpture:20,ballX:3,birdX:3,waveSpeed:0,ballSpeed:0,birdSpeed:0,bokehLights:true,rayTargets:'person,background',grid:false};
