export const tourSteps=[
 {id:'focus',target:'focus',view:'camera',title:['Eine Ebene wird scharf','Bring one plane into focus'],task:['Fokussiere auf die Person bei 4 m. Tippe sie im Bild an oder verändere den Fokus.','Focus on the person at 4 m. Tap them in the image or change focus.'],why:['Die Strahlen der fokussierten Ebene treffen sich auf dem Sensor. Davor und dahinter entstehen Flächen statt Punkte.','Rays from the focused plane meet on the sensor. Other distances form areas instead of points.'],start:scene({focus:2}),end:{focus:4},check:s=>Math.abs(effective(s).focus-(s.subject+s.cameraBack))<.15},
 {id:'aperture',target:'aperture',view:'camera',title:['Mehr Toleranz für Entfernung','More tolerance for distance'],task:['Schließe die Blende bis mindestens ƒ/8. Beobachte Hintergrund und Lichtkegel.','Stop down to at least f/8. Watch the background and light cone.'],why:['Der engere Kegel erzeugt bei Defokus kleinere Flecken. Die fokussierte Ebene bleibt dieselbe; größer wird der akzeptabel scharfe Bereich. Zeitautomatik hält die Helligkeit.','A narrower cone makes smaller defocus spots. The focused plane stays the same; the acceptably sharp range grows. Auto shutter maintains brightness.'],start:scene(),end:{aperture:11},check:s=>effective(s).aperture>=8},
 {id:'zoom',target:'focal',view:'camera',title:['Ausschnitt ist nicht Perspektive','Framing is not perspective'],task:['Wähle mindestens 85 mm. Der Kamerastandpunkt bleibt fest.','Choose at least 85 mm. Keep the camera viewpoint fixed.'],why:['Zoom zeigt einen engeren Ausschnitt. Erst ein anderer Standpunkt verändert die räumlichen Größenverhältnisse.','Zoom narrows framing. Only a different viewpoint changes spatial size relationships.'],start:scene({focal:35,aperture:4}),end:{focal:85},check:s=>s.focal>=85&&s.cameraBack===0},
 {id:'motion',target:'time',view:'controls',title:['Zeit zeichnet Bewegung','Time records motion'],task:['Verkürze die Zeit auf 1/1000 s oder kürzer. Die Automatik gleicht die Belichtung an.','Choose 1/1000 s or faster. Automatic exposure compensates.'],why:['Jede Belichtung sammelt Positionen über eine Zeitspanne. Eine kurze Zeit begrenzt die Bewegungsspur; Abspielen allein ändert diese Zeit nicht.','An exposure collects positions over time. A short exposure limits motion trails; Play alone does not change exposure time.'],start:scene({focal:50,aperture:4,mode:'S',autoISO:true,time:1/15,speed:3,motion:true}),end:{time:1/1000},check:s=>effective(s).time<=1/1000},
 {id:'night',target:'auto-setup',view:'controls',title:['Wenig Licht verlangt eine Entscheidung','Low light requires a choice'],task:['Schalte die Automatik ein. Vergleiche Zeit und ISO mit der dunklen Ausgangsaufnahme.','Enable Auto setup. Compare shutter speed and ISO against the dark initial image.'],why:['Es gibt keinen kostenlosen Helligkeitsgewinn: längere Zeit riskiert Bewegung, größere Öffnung verringert Schärfentiefe. ISO verstärkt das Signal und sammelt keine Photonen.','Brightness has trade-offs: longer exposure risks motion; a larger opening reduces depth of field. ISO amplifies the signal and collects no photons.'],start:scene({scene:'night',ev:5,temperature:3800,wb:3800,aperture:4,time:1/125,mode:'M'}),end:{mode:'P',autoISO:true,autoFocus:true,autoWB:true},check:s=>(s.mode!=='M'||s.autoISO)&&Math.abs(metrics(s).offset+meteredEV(effective(s))-s.ev-s.comp)<.4},
 {id:'pupil',target:'aperture',view:'optics',detail:'aperture',title:['Die Öffnung zeichnet mit','The opening shapes the blur'],task:['Wähle im Optiklabor die Fledermaus-Maske. Vergleiche Öffnung, Lichtfleck und Foto.','Choose the bat mask in the optics lab. Compare the opening, light spot and photo.'],why:['Ein defokussierter kleiner Lichtpunkt bildet näherungsweise die wirksame Pupille ab. Die Maske kostet Licht; Zeitautomatik kompensiert ihre Fläche. Das ist keine Lochkamera-Projektion.','A small defocused light source approximately images the effective pupil. The mask loses light; auto shutter compensates its area. This is not a pinhole-camera projection.'],start:scene({aperture:2,pupilShape:'iris',bladeCount:5}),end:{pupilShape:'bat'},check:s=>s.pupilShape==='bat'},
 {id:'curtains',target:'time',view:'optics',detail:'shutter',title:['Ein schmaler Spalt kann kurz belichten','A narrow slit can expose briefly'],task:['Verkürze im Verschlusslabor die Zeit bis 1/1000 s. Beobachte den Spalt vor dem Sensor.','Choose 1/1000 s in the shutter lab. Watch the slit in front of the sensor.'],why:['Bei kurzer Zeit folgt der zweite Vorhang schon, bevor der erste ganz geöffnet hat. Jede Sensorzeile bekommt die eingestellte Dauer. Der gesamte Durchlauf dauert länger.','At short exposure times the second curtain follows before the first fully opens. Each sensor row receives the selected duration. The complete sweep takes longer.'],start:scene({mode:'S',autoISO:true,time:1/30,focal:50}),end:{time:1/1000},check:s=>effective(s).time<=1/1000}
];
