export function interpolatedDemo(step,progress,reduced=false){const p=reduced?(progress>=.45?1:0):Math.min(1,Math.max(0,progress/.65)),q=p*p*(3-2*p),out={...step.start};for(const [key,value]of Object.entries(step.end)){const initial=step.start[key];out[key]=typeof value==='number'?(value>0&&initial>0&&['aperture','time','iso','focus','focal'].includes(key)?Math.exp(Math.log(initial)+(Math.log(value)-Math.log(initial))*q):initial+(value-initial)*q):q<.5?initial:value;}if(reduced)out.motion=false;return out;}
